// 手機殼班 B5：本地 plugin ns-restart 的 build（寫法同 tauri-plugin-tt-notice）。
// 產生 permissions/autogenerated/**（進版控、.gitattributes 鎖 LF）；Android target 時把 tauri-api
// 複製進 android/.tauri/tauri-api（gitignore）並送 cargo:android_library_path——gen/android 一個字都不動。

// restart_app 平常由 Rust 端（backup 還原、雲端還原、重新開始）經 run_mobile_plugin 呼叫，
// 不走 webview IPC；列進 COMMANDS 是讓 JS 也叫得到（沙盒原型用 devtools 觸發、之後留著無妨）。
const COMMANDS: &[&str] = &["restart_app"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).android_path("android").build();
}
